def n_hot(psi_c):
    """Energetic-ion density as a function of the shifted canonical toroidal momentum."""
    s = (psi_c - psi_axis) / (psi_edge - psi_axis)
    return args.nh_scale * itpa_density(xp.sign(s) * xp.sqrt(xp.abs(s)))

